insert into public.mushroom_growth_conditions (slug,best_after,soil_conditions,microhabitat,foraging_difficulty,foraging_tips,source,verified) values 
('amanita_battarrae','Sommer bis Herbst, Hauptzeit Juli-Oktober. Erscheint einzeln bis gesellig nach durchdringenden Sommer- und Frühherbstregen, sobald der Boden in montanen Lagen wieder durchfeuchtet ist; meist 1-2 Wochen nach ergiebigem Niederschlag in warm-feuchten Phasen.','Saure, nährstoffarme Wald- und Rohhumusböden; bevorzugt bodensauer-montane Standorte, oft an mit Moosen und Heidelbeere bestandenen Stellen.','Mykorrhiza-Partner: Symbiont von Fichte, Buche, Birke und Kiefer in Nadel-, Misch- und Laubwald, vor allem in höheren, montanen Lagen. Wächst am Boden, gern an Wegrändern, Böschungen und in lichten, moosigen Waldpartien.','experte','Scheidenstreifling ohne Stielring und ohne Knolle, mit häutiger Scheide an der Stielbasis und stark gerieftem Hutrand; kennzeichnend ist der zweifarbige, oliv-graubraune Hut mit dunklerer Mitte. NUR gut durcherhitzt essbar - roh giftig. Verwechslungsgefahr mit tödlich giftigen Knollenblätterpilzen (Amanita phalloides/virosa) und dem Pantherpilz, besonders im jungen Ei-Stadium: jeden Fund komplett ausgraben, auf Ring/Knolle/Lamellen prüfen. Nur für sehr erfahrene Sammler mit sicherer Amanita-Kenntnis.','Recherche geprüft via WebSearch (123pilzsuche, pilzbuch-pilzwelten, Wikipedia): Amanita vaginata-Gruppe, Mykorrhiza Fichte/Buche/Birke, saure montane Böden, roh giftig + Amanita-Verwechslung bestätigt.',false),
('amanita_submembranacea','Spätsommer bis Herbst, Hauptzeit August-Oktober (mit erster Welle teils ab Mai/Juni). Fruchtet nach feuchten Phasen im montanen Nadel- und Mischwald, typisch einige Tage bis zwei Wochen nach kräftigem Regen in der zweiten Sommerhälfte.','Saure, basenarme Böden montaner Nadelwälder; gern auf Rohhumus, moosigem Untergrund und an Moorrändern.','Mykorrhiza-Partner: Symbiont von Fichte, Tanne, Kiefer und Birke, vor allem in montanen Nadel- und Mischwäldern auf sauren Böden. Wächst bodenständig, oft an feuchteren, moosreichen Stellen und Moorrändern.','experte','Graubraun-olivlicher Scheidenstreifling mit grauen Velumflocken auf dem Hut, häutig-grauer Scheide und stark gerieftem Hutrand; kein Ring, keine Knolle. NUR gut gekocht essbar - roh giftig. Wegen der Zugehörigkeit zu Amanita hohe Verwechslungsgefahr mit tödlichen Knollenblätterpilzen und dem Pantherpilz, vor allem im Ei-Stadium: stets vollständig ausgraben und Stielbasis prüfen. Nur für Sammler mit sicherer Gattungskenntnis.','Recherche geprüft via WebSearch (Wikipedia, fundkorb, pilzbuch-pilzwelten): Mykorrhiza Fichte/Tanne/Kiefer/Birke, saure montane Böden, Saison Spätsommer-Herbst, Amanita-Verwechslung bestätigt.',false),
('apioperdon_pyriforme','Sommer bis Spätherbst, Hauptzeit Juli-November. Erscheint büschelig in grosser Zahl nach feuchten Perioden auf Totholz, oft schubartig wenige Tage nach ergiebigem Regen; verträgt die feuchte Herbstwitterung gut und fruchtet bis zu den ersten Frösten.','Wächst nicht am Boden, sondern auf Holz: morsche Laubholz- und Nadelholzstümpfe, Strünke, liegende Stämme und vergrabenes Holz/Holzmulch.','Saprobiont (Holzzersetzer) - der einzige regelmässig auf Holz wachsende Stäubling. Dicht büschelig auf morschen Stümpfen und Strünken in Wäldern, Parks und an Wegrändern; birnenförmige Fruchtkörper mit wurzelartigen weissen Myzelsträngen an der Basis.','experte','Nur ganz jung essbar, solange das Fleisch innen rein schneeweiss ist; bei gelb-bräunlicher oder olivlicher Verfärbung ungeniessbar. PFLICHT: jeden Fruchtkörper längs aufschneiden - tödlich giftige junge Knollenblätterpilze (Amanita) sehen als Ei kugelig aus, zeigen im Schnitt aber Hut-/Lamellenanlagen, der Stäubling ist innen homogen weiss. Büscheliges Wachstum auf Holz und wurzelartige Stränge an der Basis grenzen ihn vom Flaschenstäubling ab. Wegen des Amanita-Ei-Risikos Sammeln nur mit Schnittkontrolle - Anfänger-untauglich.','Recherche geprüft via WebSearch (Wikipedia, 123pilzsuche, pilzbuch-pilzwelten): einziger Holz-Stäubling, jung weissfleischig essbar, Amanita-Ei-Verwechslung + Pflicht-Längsschnitt bestätigt.',false),
('bovista_plumbea','Sommer bis Herbst, Hauptzeit Juni-Oktober. Fruchtet auf kurzgrasigen Wiesen und Weiden nach Regen in warmen Perioden, oft einige Tage nach ergiebigem Niederschlag; die kleinen Fruchtkörper erscheinen gesellig im niedrigen Gras.','Nährstoffarme bis mässig gedüngte Wiesen- und Weideböden; bevorzugt kurzrasige, sonnige Magerrasen und Rasenflächen.','Saprobiont auf Grünland - kein Wald-/Mykorrhizapilz. Auf Wiesen, Weiden, Rasen und Magerrasen im kurzen Gras; kleiner Bovist, der zur Reife mit dem Substrat nur locker verbunden ist und vom Wind verfrachtet werden kann.','experte','Nur ganz jung essbar, wenn das Innere komplett rein weiss und fest ist; bei einsetzender olivgrauer Sporenreife ungeniessbar. PFLICHT: jeden kugeligen Fruchtkörper längs durchschneiden - junge tödliche Knollenblätterpilze (Amanita) können ebenfalls kugelig erscheinen, zeigen im Schnitt aber Lamellen-/Hutanlagen. Nur völlig homogen-weisses Innenfleisch ohne jede Struktur ist unbedenklich. Wegen des Amanita-Ei-Risikos nur mit konsequenter Schnittkontrolle - nicht für Anfänger.','Recherche geprüft via WebSearch (123pilzsuche, Tintling, Fundkorb, Wikipedia): Grünland-Saprobiont, jung weissfleischig essbar, Pflicht-Längsschnitt wegen Amanita-Ei bestätigt.',false),
('calvatia_utriformis','Sommer bis Herbst, Hauptzeit Juni-Oktober. Erscheint einzeln bis gesellig auf Wiesen und Magerrasen nach durchgreifenden Regenfällen in warmen Phasen, oft rund eine Woche nach ergiebigem Niederschlag; auch in subalpinen Matten.','Magere, basenarme bis mässig nährstoffreiche Wiesen-, Weide- und Heideböden; bevorzugt kurzrasige, offene Magerrasen, auch in höheren Lagen.','Saprobiont auf Offenland - kein Mykorrhizapilz. Auf Wiesen, Weiden, Magerrasen, Heiden und subalpinen Matten; grosser, beutel- bis kreiselförmiger Stäubling mit verjüngter Stielbasis, der reif felderig aufreisst und eine schüsselartige Restschale hinterlässt.','experte','Nur jung essbar, solange das Innere durchgehend rein weiss und fest ist; bei gelblich-oliver Sporenreife ungeniessbar. PFLICHT: jeden kugel-/beutelförmigen Fund längs aufschneiden - junge tödliche Knollenblätterpilze (Amanita) können kugelig wirken, zeigen im Schnitt jedoch Hut-/Lamellenanlagen, der Stäubling ist innen homogen weiss. Wegen dieses Amanita-Ei-Risikos Schnittkontrolle zwingend - kein Anfängerpilz.','Recherche geprüft via WebSearch (123pilzsuche, pilzbestimmer, naturemobile, Wikipedia): Offenland-Saprobiont Magerrasen/subalpine Matten, jung weissfleischig essbar, Pflicht-Längsschnitt wegen Amanita-Ei bestätigt.',false),
('cerioporus_squamosus','Frühlings- bis Frühsommerpilz, Hauptzeit April-Juli (vereinzelt bis September). Einer der ersten auffälligen Frühjahrspilze; schiebt nach den ersten milden, feuchten Frühlingswochen rasch an Laubbäumen, oft schon kurz nach ergiebigem Frühjahrsregen.','Kein Bodenpilz - wächst direkt am Holz; bevorzugt kalkreichere, frische bis feuchte Auen- und Laubwaldstandorte sowie Parkbäume.','Schwächeparasit und Saprobiont an lebenden und toten Laubbäumen, vor allem an Ahorn, Ulme, Buche, Walnuss und Esche; in Auen- und Laubwäldern, Parks und an Strassenbäumen. Konsolen einzeln oder dachziegelig übereinander, seitlich oder kurz seitlich gestielt mit schwärzlicher Stielbasis.','anfaenger','Markanter, kaum zu verwechselnder Konsolenpilz: grosser, fächerförmiger Hut mit konzentrischen dunkelbraunen Schuppen auf hellem Grund, weisse Poren statt Lamellen, schwarze Stielbasis und auffällig mehlig-gurkiger Geruch. Nur jung essbar, solange das Fleisch weich ist - im Alter korkig-zäh und ungeniessbar. Keine giftigen Doppelgänger; allenfalls mit dem ebenfalls harmlosen Sklerotienporling verwechselbar.','Recherche geprüft via WebSearch (Wikipedia, 123pilzsuche, pilzkurse.com CH, fungiversum): Porling an Laubholz (Ahorn/Ulme/Buche), Frühjahr April-Juli, jung essbar, mehlig-gurkiger Geruch, keine giftigen Verwechsler bestätigt.',false),
('clavariadelphus_truncatus','Spätsommer bis Herbst, Hauptzeit Aug–Okt (in Bergnadelwäldern oft erst ab September). Fruchtet schubweise rund 1–2 Wochen nach ergiebigem Regen bei noch milden Bodentemperaturen; mag feucht-warme Phasen nach den ersten Spätsommer-Niederschlägen. In höheren Lagen entsprechend später.','Strikt kalk- bis basenliebend (kalkhaltige, gut durchlässige Waldböden); meidet saure Standorte. Bevorzugt eher magere, moosige Nadelstreu auf Kalk.','Bergnadelwald auf Kalk, terrestrisch in der Nadelstreu unter Fichte und Tanne (vermutlich mykorrhizal/saprob assoziiert). Zeigerumfeld: kalkliebende Bergmischwälder, oft zusammen mit Moos- und Kalkzeigern; eher submontan bis montan.','mittel','Eindeutige keulen-/kreiselförmige Fruchtkörper mit auffällig flach abgestutztem, oft eingedelltem Scheitel und runzeliger ocker- bis orangegelber Oberfläche, Fleisch mild und leicht süsslich (KOH färbt blutrot). Hauptverwechsler ist die häufigere Herkuleskeule (Clavariadelphus pistillaris) mit spitz-gerundetem statt abgestutztem Scheitel und bitterem Fleisch – essbar, aber bitter, daher Geschmacksprobe (ausspucken) hilft. Keine tödlichen Doppelgänger, jedoch in der Schweiz vergleichsweise selten (in DE Rote Liste) – nur einzeln und massvoll entnehmen.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)',false),
('clavulina_cinerea','Hochsommer bis Spätherbst, Hauptzeit Aug–Nov, schubweise ca. 1–2 Wochen nach ergiebigem Regen bei milden 10–18 °C. Profitiert von feuchten Herbstwochen und hält bis zu den ersten leichten Frösten durch.','Anspruchslos bezüglich pH, auf humosen Wald- und Wegrandböden; sowohl auf basenreichen wie mässig sauren Substraten. Mag feuchte, beschattete Bodenstellen.','Terrestrisch in Laub-, Nadel- und Mischwald sowie an Wegrändern, gesellig in Gruppen/Reihen. Gilt als Mykorrhiza-Bildner mit diversen Bäumen; Zeigerumfeld: moosige, humose Waldböden, oft an Pfaden und Böschungen.','mittel','Graue bis bleigraue, mehrfach unregelmässig verzweigte Koralle mit stumpfen, etwas abgeflachten Astspitzen; Fleisch zäh-elastisch. Nur bedingt essbar (jung und durchgegart; ältere/rohe Stücke können leicht abführend wirken) – nur junge, feste Exemplare sammeln. Verwechslung v. a. mit grauen Formen der weissen Korallen (Clavulina coralloides/rugosa) sowie mit Ramaria-Arten, von denen einige abführend giftig sind; Clavulina lässt sich makroskopisch von Ramaria abgrenzen (Astspitzen, Konsistenz). Im Zweifel Finger weg.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)',false),
('clavulina_coralloides','Sommer bis Spätherbst, Hauptzeit Jul–Nov, schubweise einige Tage bis 2 Wochen nach Regen bei feucht-milder Witterung. Einer der früher erscheinenden Korallenpilze, hält bei mildem Herbst lange durch.','Auf humosen, eher frischen bis feuchten Waldböden; weitgehend bodenvag (kalkliebend bis mässig sauer), auch auf nackter Erde an Wegrändern.','Terrestrisch in Laub-, Nadel- und Mischwald sowie an Wegböschungen, einzeln bis gesellig. Mykorrhiza-Partner verschiedener Bäume; Zeigerumfeld: moosige, offene Bodenstellen und Pfadränder im Wald.','mittel','Weisse bis cremeweisse, dicht und fein verzweigte Koralle mit charakteristisch zugespitzten, kammartig gezähnten Astspitzen; Fleisch zäh. Nur bedingt essbar – jung und gut durchgegart, ältere Stücke geschmacklich/verträglich grenzwertig. Achtung: häufig durch den Pilzparasiten Helminthosphaeria grau überzogen, dann leicht mit der Grauen Koralle verwechselbar. Hauptrisiko sind ähnliche Ramaria-Arten (z. T. abführend) – nur typisch weisse, kammspitzige, junge Exemplare nehmen und im Zweifel verwerfen.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)',false),
('clavulina_rugosa','Hochsommer bis Spätherbst, Hauptzeit Aug–Nov, schubweise ca. 1–2 Wochen nach ergiebigem Regen bei milden Temperaturen. Hält bei feuchtem Herbst bis zu den ersten Frösten durch.','Auf humosen Wald- und Wegrandböden, bodenvag (kalkhaltig bis mässig sauer); bevorzugt frische, leicht beschattete Stellen.','Terrestrisch in Laub-, Nadel- und Mischwald sowie an Wegrändern und Böschungen, einzeln bis büschelig. Mykorrhiza-Bildner mit verschiedenen Bäumen; Zeigerumfeld: moosige Pfadränder und offene Bodenstellen im Wald.','mittel','Weissliche bis cremefarbene, meist nur wenig (gabelig) verzweigte, runzelig-längsfaltige Keule – derber und gröber als die fein-kammspitzige Kammkoralle. Fleisch zäh, nur bedingt essbar (jung, durchgegart). Verwechslung mit anderen weissen/grauen Clavulina-Arten und mit weisslichen Clavaria/Ramaria; einige Ramaria wirken abführend. Nur junge, typisch runzelige Exemplare sammeln, ältere und parasitär vergraute Stücke meiden – im Zweifel stehen lassen.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)',false),
('cortinarius_praestans','Spätsommer bis Herbst, Hauptzeit Sep–Okt (ab Aug möglich), schubweise rund 1–2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei noch milder, wärmeliebender Witterung. Reagiert deutlich auf die ersten grossen Herbstniederschläge.','Strikt kalk-/basenliebend: warme, kalkhaltige, meist naturnahe Laubwaldböden; meidet bodensaure Standorte.','Mykorrhiza-Partner v. a. der Buche, daneben Eiche und Hainbuche; thermophiler Kalk-Laubwald (Buchen-/Eichenwald). Zeigerumfeld: lichte, warme Kalkbuchenwälder mit Kalkzeigerpflanzen im Unterwuchs.','experte','Grosser, fleischiger Schleimkopf mit anfangs eingerolltem, braun-violett überlaufenem Hut mit weisslichen Velumfasern/-flecken und kräftigem, oft blau-violett angehauchtem Stiel mit Cortina (Schleier); junge Lamellen tonbraun. Gilt als einziger marktfähiger Schleierling – ABER die Gattung Cortinarius enthält tödlich giftige Arten (u. a. der orellaninhaltige Orange-/Spitzgebuckelte Raukopf mit Spätnieren-Versagen). Daher nur für Erfahrene: Rostbraunes Sporenpulver und alle Eulen-Merkmale müssen passen; jede Unsicherheit, kleinere/schlanke oder leuchtend orange-braune Schleierlinge strikt meiden. Im Zweifel zur Pilzkontrolle.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; VAPKO/Schweizer Speisepilz-Verordnung; gängige Pilzführer (Laux, Gerhardt)',false),
('cuphophyllus_pratensis','Herbstpilz, Hauptzeit Sep–Nov, schubweise einige Tage bis ~2 Wochen nach ergiebigem Herbstregen bei kühl-milder, taureicher Witterung. Erscheint typischerweise erst nach den ersten kühleren, feuchten Herbsttagen und übersteht leichte Fröste.','Magere, ungedüngte, eher basenreiche bis neutrale Grünlandböden; meidet stickstoffüberdüngte Fettwiesen. Mag intakte, alte Magerrasen.','Saprobiontisch im kurzrasigen Magergrünland: ungedüngte Magerwiesen, Weiden, Parkrasen und Böschungen, gesellig in Gruppen/Hexenringen. Zeigerumfeld: artenreiche Magerwiesen mit weiteren Saftlingen (Hygrocybe), Zeiger für nährstoffarme, naturnahe Wiesen.','experte','Orange-lachsfarbener bis cremebrauner, im Alter blass aufschirmender Hut mit weit am Stiel herablaufenden, dicklich-entferntstehenden Lamellen in Hutfarbe und weissem Sporenpulver; Stiel hutfarben-blass, ohne Ring. ACHTUNG Wiesen-Falle: in genau denselben Magerwiesen wachsen kleine weisse, muscarinhaltige Trichterlinge (Clitocybe dealbata/rivulosa-Gruppe), deren herablaufende Lamellen Anfänger täuschen – Verwechslung kann schwere Vergiftungen verursachen. Nur mit sicherer Saftlings-Erfahrung sammeln: wachsartige Konsistenz, dicke entfernte Lamellen, kein mehlig-ranziger Trichterlings-Geruch; im Zweifel stehen lassen (zudem in DE/teils CH geschützt – schonen).','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)',false),
('cuphophyllus_virgineus','Hauptzeit September–November (in milden Lagen bis Dezember); erscheint einige Tage bis ~2 Wochen nach ergiebigem Herbstregen bei kühlem Wetter (ca. 6–14 °C), oft truppweise und gern nach den ersten Nachtfrösten.','Magere, ungedüngte, eher saure bis neutrale Böden; bevorzugt nährstoffarme, mässig frische bis trockene Standorte ohne Düngung.','Kein Mykorrhizapilz, sondern saprob im Grasfilz von Magerwiesen, Weiden, moosigen Rasen, Parkrasen und Friedhöfen. Zeigerstandort sind ungedüngte Saftlingswiesen (Magerrasen mit Moospolstern).','experte','Auf ungedüngten Magerwiesen nach kleinen, rein- bis glasigweissen, etwas durchscheinenden Fruchtkörpern mit schmierig-fettigem Hut, weit herablaufenden, entfernten weissen Lamellen und mildem Geschmack suchen. ACHTUNG – im selben Wiesen-Habitat wachsen tödlich giftige weisse Trichterlinge (Clitocybe rivulosa, C. dealbata) mit gedrängten, nicht weit herablaufenden Lamellen und mehligem Geruch sowie weisse Risspilze. Nur bei zweifelsfreier Bestimmung (wachsartige, weit herablaufende Lamellen, schmieriger Hut) sammeln; für Anfänger wegen der lebensgefährlichen weissen Wiesenpilze nicht geeignet.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia',false),
('disciotis_venosa','Frühjahr, Hauptzeit März–Mai (parallel zur Morchelsaison); erscheint nach mildem, feuchtem Vorfrühlingswetter etwa 1–2 Wochen nach Regen, sobald die Böden sich auf ca. 8–14 °C erwärmen, oft an denselben Stellen wie Morcheln.','Feuchte, humose, eher kalkhaltige bis neutrale Böden; bevorzugt nährstoffreiche, frische bis nasse Auen- und Uferböden.','Kein Mykorrhizapilz, sondern saprob auf humosen, feuchten Böden in Auwäldern, Laubwäldern, an Ufergehölzen, Wegrändern und in Gebüschen. Zeigerstandorte sind feuchte Auen- und Hangwälder mit Eschen, Erlen und Weiden.','experte','Flache, becher- bis tellerförmige, braune Fruchtkörper mit aussen weisslicher, kleiig-höckeriger Unterseite und im Alter gerippt-aderiger Innenseite suchen; typisch ist der deutliche Chlor-/Javel-Geruch (verschwindet beim Kochen). NUR gut durchgegart geniessbar – roh giftig. Abzugrenzen von Lorcheln/Scheibenlorcheln (Gyromitra/Discina: kein Chlorgeruch, meist an Nadelholz, giftiges Gyromitrin) und geruchlosen Becherlingen (Peziza). Wegen der giftigen Lorchel-Verwechsler und der Roh-Giftigkeit nur für erfahrene Sammler.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia',false),
('gymnopus_dryophilus','Lange Saison Mai–November mit Hauptzeit Spätsommer/Herbst; erscheint schubweise einige Tage nach Regen bei milden Temperaturen (ca. 10–18 °C), häufig truppweise im Falllaub.','Saure, humose Wald- und Streuböden; bevorzugt mässig frische, nährstoffärmere Standorte mit dicker Laub-/Nadelstreu.','Kein Mykorrhizapilz, sondern saprob auf Falllaub, Nadelstreu und morschem Holz in Laub-, Nadel- und Mischwäldern, besonders unter Eichen und Buchen. Zeigerstandort sind streureiche, bodensaure Wälder.','experte','Kleiner Rübling mit je nach Feuchte gelb- bis kastanienbraunem, hygrophanem Hut (trocken creme/weisslich), zähem, glattem Stiel und blassen, gedrängten Lamellen; nur jung, gut durchgegart und in kleinen Mengen geniessbar (bei empfindlichen Personen Magen-Darm-Reizung, daher nur bedingt essbar). ACHTUNG – kleiner brauner Pilz mit zahlreichen, oft nur mikroskopisch trennbaren Rübling-Doppelgängern; im selben Streu-/Holz-Habitat wächst der tödliche Gift-Häubling (Galerina marginata, brauner Sporenstaub, häutiger Ring). Wegen der Verwechslungsgefahr mit kleinen braunen Giftpilzen nur für erfahrene Sammler.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia',false),
('gyroporus_cyanescens','Hauptzeit Juli–Oktober (vereinzelt ab Juni); erscheint einige Tage bis ~2 Wochen nach durchdringendem Sommer-/Herbstregen bei warmen Bodentemperaturen (ca. 14–20 °C), meist einzeln oder in kleinen Gruppen.','Saure, sandige bis kiesige, magere Böden; meidet kalkreiche Standorte und bevorzugt gut drainierte, nährstoffarme Sauerböden.','Mykorrhizapilz an Laub- und Nadelbäumen, vor allem Birke, Kiefer und Eiche, in lichten Wäldern, an Wegrändern und Sandgruben auf Sauerboden. Zeigerstandort sind sandige, saure Birken-/Kiefernwälder und Heidekiefernwälder.','mittel','In sandigen, sauren Birken-/Kiefernwäldern nach blass strohgelbem bis ockerlichem, fein filzigem Röhrling mit brüchigem, kammerig-hohlem Stiel suchen. Entscheidendes Bestimmungsmerkmal: das weisslich-gelbe Fleisch und die Poren laufen beim Anschneiden bzw. Druck sofort intensiv kornblumenblau an. Verwechslungsarm, da kein gefährlicher Röhrling so rasch und intensiv blaut und gleichzeitig den brüchigen Hohlstiel zeigt; im Zweifel die schlagartige Blauverfärbung und den hohlen Stiel prüfen.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)',false),
('hydnum_albidum','Hauptzeit August–November; erscheint einige Tage bis ~2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei mildem Wetter (ca. 8–16 °C), oft gesellig in Hexenreihen oder Gruppen.','Kalkhaltige, basenreiche, humose Böden; bevorzugt frische, mässig nährstoffreiche Standorte mit Moos- und Laubauflage.','Mykorrhizapilz an Laub- und Nadelbäumen (Buche, Eiche, Hainbuche, Fichte) in Laub- und Mischwäldern auf Kalk. Zeigerstandort sind moosige, kalkhaltige Buchen-/Mischwälder.','anfaenger','Der weissliche Semmelstoppelpilz trägt auf der Hutunterseite statt Lamellen oder Röhren weiche, herablaufende Stacheln (Stoppeln) – dieses Merkmal schliesst eine Verwechslung mit giftigen Blätter- oder Röhrenpilzen praktisch aus und macht die Gattung anfängertauglich. Hut weisslich bis blass cremefarben, Fleisch fest, mild, kaum madig. Alle Semmelstoppelpilz-Arten (auch H. repandum, H. rufescens) sind essbar; eine genaue Artbestimmung ist für die Küche nicht sicherheitskritisch. Stets gut durchgaren, ältere Stücke können leicht bitter sein.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia',false),
('hygrophorus_eburneus','Hauptzeit September–November; erscheint einige Tage bis ~2 Wochen nach ergiebigem Herbstregen bei kühlem Wetter (ca. 6–14 °C), oft truppweise unter Buchen.','Kalkreiche, basenreiche Laubwaldböden; bevorzugt frische, gut mit Buchen-Laubstreu versorgte Standorte.','Mykorrhizapilz vor allem an Rotbuche (Fagus sylvatica) in kalkreichen Buchen- und Laubmischwäldern. Zeigerstandort sind kalkhaltige Buchenwälder (Buchen-Kalkwälder).','experte','Der Elfenbein-Schneckling hat einen rein elfenbeinweissen, stark schleimig-glitschigen Hut, weisse, weit herablaufende, dicke Lamellen und einen schmierigen Stiel; mild, aber kulinarisch nur mässig und schleimig (bedingt essbar). ACHTUNG – im selben Buchen-Kalkwald wachsen tödlich giftige weisse Pilze: weisse Trichterlinge (Clitocybe, Muscarin) und weisse Wulstlinge/Knollenblätterpilze (Amanita: Scheide, Ring). Wegen dieser lebensgefährlichen weissen Doppelgänger nur für erfahrene Sammler; im Zweifel den auffällig dicken Schleim, die weit herablaufenden Lamellen und das Fehlen von Scheide/Ring prüfen.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia',false),
('hygrophorus_hypothejus','Ausgesprochener Spätherbst- bis Winterpilz, Hauptzeit Oktober bis Dezember (teils bis in milde Januartage). Braucht die ersten Nachtfröste als Auslöser - schiebt erst nach Kälteeinbruch, oft wenn die meisten anderen Pilze schon durch sind. Nach Frostnächten plus etwas Feuchtigkeit erscheint er gesellig in Trupps unter Föhren.','Saure, magere Sandböden. Wärmebegünstigte, lichte Föhrenstandorte; meidet Kalk und nährstoffreiche Lagen.','Mykorrhiza-Partner der Wald-Föhre/Kiefer (Pinus sylvestris). Wächst am Boden in lichten Kiefernwäldern, an Wegrändern, auf Heideflächen und in der Nadelstreu - praktisch immer im direkten Wurzelbereich von Kiefern.','mittel','Kennzeichnend sind der schleimig-klebrige, oliv-braune Hut, die gelblichen, etwas herablaufenden Lamellen und der gelbliche, oben oft beringt wirkende, schmierige Stiel - alles bei kühler Spätsaison unter Kiefern. Abzugrenzen ist der Natternstielige Schneckling (Hygrophorus olivaceoalbus) mit weisslichen Lamellen und braun genattertem Stiel; giftige Doppelgänger gibt es in der Gruppe nicht, dennoch Schnecklinge nur bei sicherer Gattungskenntnis sammeln.','Recherche-Angabe geprüft via WebSearch (Frost-Auslöser, Kiefern-Mykorrhiza, saurer Sandboden, Verwechslung Natternstieliger Schneckling bestätigt; pilzfinder.de, mushroom-toxin.de)',false),
('hypholoma_capnoides','Saprob auf Nadelholz, Hauptzeit September bis November, in milden Wintern bis Februar/März an frostfreien Tagen. Erscheint büschelig nach feuchten Phasen im Spätherbst; verträgt leichten Frost und schiebt oft noch, wenn das Laubwald-Aufkommen vorbei ist.','Kein Mykorrhiza-Pilz - Holzzersetzer ohne Bodenbindung; wächst direkt auf morschem Nadelholz unabhängig vom Bodentyp.','Büschelig auf Stümpfen und liegendem Totholz von Nadelbäumen, bevorzugt Fichte und Kiefer. Typisch an vermoosten Stubben in Nadel- und Mischwäldern.','experte','Sichere Merkmale: graue bis graubraune (nie gelbe oder grüne) Lamellen, milder Geschmack und das Wachstum auf Nadelholz. Strikt abzugrenzen vom giftigen Grünblättrigen Schwefelkopf (Hypholoma fasciculare), der oft am selben Stumpf wächst, aber schwefelgelbe bis grünliche Lamellen und einen bitteren Geschmack hat. Im Zweifel Lamellenfarbe und Bitterkeit prüfen - nur zweifelsfrei graublättrige, milde Büschel mitnehmen.','Recherche-Angabe geprüft via WebSearch (graue Lamellen + milder Geschmack als Trennung zum giftigen H. fasciculare, Nadelholz-Substrat, Spätherbst/Winter bestätigt; fungiversum.de, gizbonn.de, dikarbion.eu)',false),
('infundibulicybe_gibba','Sommer- bis Herbstpilz, Hauptzeit etwa Juni/Juli bis Oktober. Erscheint einzeln bis gesellig nach durchdringenden Sommerregen in der Laubstreu; reagiert recht zügig auf Niederschlag in warmen, feuchten Phasen.','Kein Mykorrhiza-Pilz - Streuzersetzer; auf Laub- und Nadelstreu frischer bis mässig nährstoffreicher Waldböden, ohne enge Bodentyp-Bindung.','Saprob in der Streuschicht von Laub-, Nadel- und Mischwäldern, an Waldrändern, Wegböschungen und auf Lichtungen. Wächst gern dort, wo sich Laub und Nadeln am Boden sammeln.','experte','Erkennbar am ockerbräunlichen, trichterig vertieften Hut mit kleinem Buckel im Zentrum, den weisslichen, weit herablaufenden Lamellen und dem deutlichen, oft mehlartigen Geruch. Vorsicht: Unter den Trichterlingen gibt es kleine, rein weisse, stark bis tödlich giftige Arten (muscarinhaltige Clitocybe) - Trichterlinge generell nur bei zweifelsfreier Artbestimmung sammeln. Sensible Personen vertragen die Art zudem nicht immer, daher nur klein und im Mischgericht.','Recherche-Angabe geprüft via WebSearch (Streuzersetzer Laub-/Nadelwald, Saison Jun-Okt, Hinweis auf giftige Trichterling-Verwechsler und mögliche Unverträglichkeit bestätigt; Wikipedia, pilzbuch-pilzwelten.de, 123pilzsuche.de)',false),
('lactarius_semisanguifluus','Spätsommer bis Herbst, Hauptzeit August bis Oktober/November. Schiebt gesellig nach ergiebigen Spätsommer- und Herbstregen im Kiefernwald; nutzt feucht-milde Phasen nach längeren Niederschlägen.','Saure, magere, eher trockene Sandböden in wärmebegünstigten Kiefernlagen; meidet schwere und stark nährstoffreiche Böden.','Mykorrhiza-Partner der Kiefer/Föhre (Pinus). Wächst am Boden in lichten Kiefernwäldern, an Waldrändern und Wegböschungen, gern auf moosig-grasigen Stellen im Wurzelbereich der Kiefern.','experte','Reizker erkennt man an der Milch, die hier zunächst orange austritt und sich rasch über weinrot zu weinbraun verfärbt, sowie an grünlichen Verfärbungen am Hut. Innerhalb der Milchlinge gibt es viele scharf schmeckende, ungeniessbare bis unverträgliche Arten - sichere Reizker-Bestimmung über Milchfarbe, Milchverfärbung und Nadelbaum-Partner ist Pflicht. Sehr ähnlich ist der Fichtenreizker (L. deterrimus); zur Unterscheidung auf festeres Fleisch, nie schleimigen Hut und Kiefern als Partner achten.','Recherche-Angabe geprüft via WebSearch (Kiefern-Mykorrhiza auf sauren Sandböden, Milchverfärbung orange->weinrot->weinbraun, Abgrenzung zu L. deterrimus bestätigt; Wikipedia Edel-Reizker, pilzbuch-pilzwelten.de, pilz-baden.ch)',false),
('lactarius_subdulcis','Sommer bis Spätherbst, Hauptzeit Juli bis Oktober/November. Erscheint gesellig in kleinen Grüppchen nach Regenphasen unter Buchen; recht treuer Begleiter feuchter Buchenwald-Abschnitte.','Frische bis feuchte, eher saure Laubwaldböden; an Bodentyp wenig wählerisch, solange Buchen als Partner vorhanden sind.','Mykorrhiza-Partner der Buche (Fagus). Wächst am Boden in Buchen- und Buchenmischwäldern, oft im Moos oder in der Laubstreu direkt unter Buchen; charakteristisch ein wolliges Myzelbüschel an der Stielbasis.','experte','Kleiner, rotbrauner Milchling mit weisser, unveränderlicher Milch, die erst süsslich, dann leicht bitter schmeckt, und feucht-fettig glänzendem Hut. Nur bedingt essbar und geschmacklich schwach, daher höchstens als Mischpilz. Achtung: zahlreiche zierliche, ähnlich gefärbte Milchlinge sehen fast gleich aus, einige davon scharf und ungeniessbar - Milchlinge generell nur mit sicherer Artkenntnis sammeln (Milchfarbe, Geschmack, Partnerbaum prüfen).','Recherche-Angabe geprüft via WebSearch (Buchen-Mykorrhiza, weisse Milch süsslich-dann-bitter, Myzelbüschel an Stielbasis, nur bedingt essbar/Mischpilz, viele ähnliche Milchlinge bestätigt; Wikipedia, pilzbuch-pilzwelten.de, tintling.com)',false),
('lepista_glaucocana','Herbst- bis Frühwinterpilz, Hauptzeit Oktober bis Dezember, bis zum ersten harten Frost. Erscheint oft in Reihen, Gruppen oder Hexenringen nach feuchten Herbstwochen; einer der spätesten Speisepilze der Saison.','Nährstoffreiche, humose, oft kalkhaltige Böden; bevorzugt gut versorgte Lagen in Wald, Park und Garten.','Kein Mykorrhiza-Pilz - Folgezersetzer auf nährstoffreichem Boden; in Laub-, Nadel- und Auwäldern, Parks, Gärten und an Wegrändern, gern auf Laub- und Kompostanhäufungen.','experte','Jung ein guter Speisepilz, erkennbar am blass ockerfarbenen Hut mit lila bis graublauem Schimmer (heller und weniger violett als der Violette Rötelritterling) und gedrängten, im Alter rötlich-ockerlichen Lamellen. Verwechslungsgefahr besteht mit giftigen Arten anderer Gattungen, insbesondere dem giftigen Wohlriechenden Trichterling (Clitocybe) - daher Hutfarbe, Lamellenfarbe und Geruch genau prüfen und nur bei sicherer Bestimmung sammeln.','Recherche-Angabe geprüft via WebSearch (Folgezersetzer nährstoffreicher Boden, Spätherbst bis Frost, blass ocker-lila Hut, Verwechslung mit giftigem Wohlriechenden Trichterling bestätigt; pilzbuch-pilzwelten.de, mykopedia.org, 123pilzsuche.de)',false),
('lycoperdon_echinatum','Juli bis Oktober. Erscheint nach ergiebigen Sommer- und Frühherbstregen bei feucht-warmer Witterung, oft schubweise eine knappe Woche nach durchdringendem Landregen. Beste Funde nach mehreren feuchten Tagen im schattig-humosen Buchenwald.','Bevorzugt kalkhaltige, basenreiche und humusreiche Waldböden; gedeiht auf der Laubstreu- und Humusauflage, nicht auf Holz.','Saprobiont im Laub- und Buchenwald auf Humus und Falllaub, gern an krautreichen, kalkbeeinflussten Stellen. Zeigerpflanzen kalkreicher Buchenwälder (z.B. Waldmeister, Bingelkraut) markieren gute Standorte.','experte','Nur ganz junge, innen rein weiße Fruchtkörper sind essbar; sobald das Innere gelblich oder olivbraun wird (Sporenreife), ist der Pilz ungenießbar. JEDEN Stäubling vor der Verwendung längs halbieren: ist innen eine Hutkappe, Lamellenansatz oder eine gegliederte Silhouette zu sehen, handelt es sich um ein lebensgefährliches Knollenblätterpilz-Ei (Amanita) und niemals um einen Stäubling. Der Igel-Stäubling ist an den langen, oft an der Spitze gebogenen, in Büscheln zusammenneigenden Stacheln erkennbar.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt, Der grosse BLV Pilzführer',false),
('mitrophora_semilibera','Mitte März bis Mai. Frühjahrspilz; erscheint nach milden, regnerischen Phasen sobald die Böden sich erwärmen, typischerweise zur Zeit der Buschwindröschen- und Bärlauchblüte. Beste Funde in feuchten Auwäldern nach mildem, niederschlagsreichem Frühlingswetter.','Feuchte, nährstoff- und basenreiche, oft kalkhaltige Auen- und Lehmböden; liebt frische bis nasse, humose Standorte in Gewässernähe.','Saprobiont/Begleiter in Auwäldern, Ufergebüschen und Laubwald, bevorzugt unter Esche, Pappel und Ulme auf feuchtem Grund. Brennnessel-, Bärlauch- und Scharbockskraut-Fluren in Flussauen sind verlässliche Begleitvegetation.','experte','Wie alle Morcheln nur durchgegart und nie roh verzehren (roh giftig); kleine Mengen, da der Pilz Unverträglichkeiten auslösen kann. Kennzeichnend ist der nur zur Hälfte mit dem Stiel verwachsene, glockige Hut (unterer Hutrand frei abstehend). Gefährlichster Verwechsler ist die Frühjahrslorchel (Gyromitra esculenta) mit hirnartig gewundenem, nicht wabig-gekammertem Hut — sie ist roh tödlich giftig; im Zweifel den Längsschnitt prüfen (echte Morcheln/Käppchenmorchel sind innen vollständig hohl).','123pilze.de; SwissFungi (WSL); DGfM; Laux, Essbare Pilze und ihre giftigen Doppelgaenger',false),
('paralepista_flaccida','August bis November. Spätsommer- bis Spätherbstpilz; erscheint nach den ersten kühleren, feuchten Herbstphasen und kräftigem Landregen, oft gesellig in Reihen und Hexenringen. Verträgt erste leichte Nachtfröste.','Frische, humusreiche Wald- und Streuböden; sowohl auf saurem Nadelstreu als auch auf neutralem bis kalkhaltigem Laubhumus.','Streuzersetzer (Saprobiont) in Nadel-, Laub- und Mischwald, auf dicker Nadel- und Laubstreu, an Wegrändern und in Parkanlagen; wächst gern gesellig in Büscheln, Reihen und Hexenringen.','experte','Nur jung und stets gut durchgegart geniessbar (roh unverträglich), Geschmack mittelmäßig — eher Sammelpilz für Kenner. Erkennungsmerkmale: fuchsig orangebrauner, im Alter tief trichterförmiger Hut, am Stiel herablaufende Lamellen und oft hygrophan ausblassende Färbung. Achtung: In der Gruppe weisser und blasser Trichterlinge (Clitocybe) gibt es stark muskarinhaltige, giftige Arten — kleine, rein weisse Trichterlinge auf Wiesen/Wegrändern niemals mit diesem Pilz verwechseln; im Zweifel stehen lassen.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt, Der grosse BLV Pilzführer',false),
('polyporus_umbellatus','Juni bis September. Sommer- bis Frühherbstpilz; der grosse Büschel erscheint nach warmen, feuchten Perioden mit ergiebigem Sommerregen, oft mehrere Jahre an derselben Stelle aus dem dauerhaften unterirdischen Sklerotium.','Nährstoffreiche, humose Laubwaldböden über dem unterirdischen Sklerotium, meist an Stümpfen und Wurzeln alter Laubbäume.','Schwächeparasit/Saprobiont an den Wurzeln von Eiche, Buche und Hainbuche; der vielhütige Fruchtkörper wächst am Boden direkt aus einem knolligen Sklerotium nahe Stammbasis, Stümpfen oder Totholz alter Laubbäume.','mittel','Nur jung und zart geniessbar, ältere Exemplare werden zäh; gut durchgaren. Kennzeichnend ist der grosse, aus einem gemeinsamen verzweigten Strunk gebildete Büschel vieler kleiner, kreisrunder, in der Mitte genabelter Hütchen mit weissen Poren — eine charakteristische, kaum giftig zu verwechselnde Gestalt. Verwechselbar mit dem ähnlich büscheligen Klapperschwamm (Grifola frondosa, ebenfalls essbar) und dem Riesenporling (Meripilus giganteus, jung essbar, alt magenreizend); tödliche Doppelgänger gibt es nicht, dennoch Bestimmung absichern.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt, Der grosse BLV Pilzführer',false),
('pseudoclitocybe_cyathiformis','September bis Dezember, bei milder Witterung bis in den Januar. Spätherbst- und Winterpilz; erscheint nach feuchten, kühlen Perioden und übersteht leichte Fröste, oft noch nach den ersten Frösten als einer der letzten Pilze des Jahres.','Frische bis feuchte, humose Wald- und Streuböden sowie morsches, am Boden liegendes Totholz; anspruchslos bezüglich Bodenreaktion.','Saprobiont in Laub-, Nadel- und Mischwald auf Humus, Streu, Holzhäcksel und vermoderndem Totholz, häufig an Wegrändern, Waldwegböschungen und in Parks; oft gesellig.','experte','Nur jung und gut gegart ein geringwertiger Speisepilz; alt zäh. Merkmale: tief trichterförmiger, kaffee- bis graubrauner, hygrophaner Hut, weit am graufaserigen Stiel herablaufende, graue Lamellen. Vorsicht in der Trichterlings-Verwandtschaft: graubraune Trichterlinge und Risspilze ähnlicher Standorte können giftig (muskarinhaltig) sein; nur bei sicherer Bestimmung anhand des typischen graufaserigen Stiels und der herablaufenden Lamellen sammeln, sonst stehen lassen.','123pilze.de; SwissFungi (WSL); DGfM; Laux, Essbare Pilze und ihre giftigen Doppelgaenger',false),
('rhodocollybia_butyracea','August bis Dezember. Spätsommer- bis Winterpilz; erscheint zahlreich nach feuchten Herbstphasen und Landregen, oft gesellig in der Nadelstreu, und hält bei milder Witterung bis in den Frühwinter durch.','Saure, humose Nadel- und Laubwaldböden; gedeiht auf der Nadel- und Laubstreuauflage, nicht direkt auf Holz.','Streuzersetzer (Saprobiont) vor allem in Fichten- und Nadelwald, auch in Buchen- und Mischwald, auf Nadelstreu und Falllaub; meist truppweise und gesellig.','experte','Nur jung und durchgegart ein geringwertiger Speisepilz, Stiel oft knorpelig-zäh und daher zu entfernen. Kennzeichnend sind der fettig-schmierige, hygrophane, rotbraune bis graubraune Hut mit hellerem Rand, der zur Basis keulig-verdickte, längsfaserige Stiel und der weisse bis blass rosafarbene Sporenstaub. Achtung: bräunliche, kleine Blätterpilze gleicher Standorte umfassen giftige Risspilze (Inocybe, muskarinhaltig) und ungeniessbare Arten — Bestimmung nur mit Sporenpulverfarbe und Stielmerkmalen absichern, im Zweifel stehen lassen.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt, Der grosse BLV Pilzführer',false),
('russula_claroflava','Hauptsaison Juli bis Oktober. Erscheint zuverlässig einige Tage nach kräftigen Sommer- und Spätsommer-Regenfällen, wenn die staunassen Moorränder gut durchfeuchtet bleiben. Da er an dauerfeuchte Birkenstandorte gebunden ist, lohnt die Suche besonders in regnerischen, milden Spätsommerwochen.','Saure, nasse bis staunasse, torfige bis humose Böden mit niedrigem pH; meidet Kalk.','Mykorrhiza-Symbiont der Birke (Betula). Typisch an Moorrändern, in Bruch- und Feuchtwäldern, oft direkt im Sphagnum-Torfmoos zwischen Birken. Zeigerstandort: vernässte Birkenbestände, Hochmoorränder.','experte','Kennzeichen: leuchtend chromgelber Hut, weisses Fleisch, das bei Verletzung und im Alter langsam grau bis schwärzlich anläuft, milder Geschmack. Als Täubling (Gattung Russula) nur für Geübte: andere gelbhütige Täublinge sind scharf und ungeniessbar, und Verwechslung mit jungen, noch nicht ausgebreiteten Lamellenpilzen anderer Gattungen ist möglich. Die Speiseprobe (Geschmackstest, ausspucken) und die typische Graufärbung absichern; im Zweifel stehen lassen.','123pilze, SwissFungi, DGfM',false),
('russula_decolorans','Hauptsaison Juli bis Oktober, Schwerpunkt im Spätsommer und Frühherbst. Fruktifiziert wenige Tage nach ergiebigen Regenfällen in feuchten Nadelwald- und Moorrandlagen; ergiebige, kühlere Herbstwochen nach Niederschlag sind am besten.','Saure, feuchte, humose bis torfige Böden über Sand oder Moor; kalkmeidend.','Mykorrhiza mit Kiefer (Pinus) und Fichte (Picea). Typisch in bodensauren Nadelwäldern, an Moorrändern und in feuchten Lagen, oft bei Heidelbeere und Torfmoos als Zeigern.','experte','Kennzeichen: orangeroter bis ziegelroter Hut, ockergelbes Sporenpulver, mildes Fleisch, das beim Altern und nach Schnitt erst grau, dann schwärzlich verfärbt. Als Russula nur für Geübte: rothütige Täublinge umfassen scharfe, ungeniessbare Arten (Verwechslergruppe). Geschmacksprobe (mild?) und die charakteristische Grau-Schwarz-Verfärbung des Fleisches zur Absicherung nutzen; scharf schmeckende Exemplare verwerfen.','123pilze, SwissFungi, DGfM',false),
('russula_integra','Hauptsaison Juli bis Oktober. Typischer Bergwaldpilz, der nach sommerlichen Gewitterregen und in feuchten Frühherbstphasen erscheint; in höheren Lagen entsprechend etwas später. Suche nach durchfeuchteten, milden Perioden in den Fichten-Tannen-Bergwäldern.','Kalkhaltige bis neutrale, humose, gut durchlüftete Bergwaldböden.','Mykorrhiza mit Fichte (Picea), Tanne (Abies) und Kiefer (Pinus). Typisch in montanen bis subalpinen Nadel- und Bergwäldern auf basenreichem Untergrund.','experte','Kennzeichen: braunroter bis kastanienbrauner Hut, ockergelbes Sporenpulver, milder, nussiger Geschmack, Fleisch verfärbt nicht. Als Täubling (Gattung Russula) nur für Geübte: zahlreiche ähnlich gefärbte Täublinge, darunter scharfe und ungeniessbare Arten. Mit Geschmacksprobe (mild, nicht scharf), Sporenpulverfarbe und Standort absichern; im Zweifel verwerfen.','123pilze, SwissFungi, DGfM',false),
('russula_nigricans','Hauptsaison Juli bis Oktober. Erscheint nach durchdringenden Sommer- und Herbstregen in Laub- und Nadelwäldern; die robusten Fruchtkörper stehen oft lange und sind auch in trockeneren Phasen noch als alte, geschwärzte Exemplare auffindbar. Junge, feste Pilze nur in feuchten Wochen.','Frische, humose Wald- und Mischwaldböden, von sauer bis neutral, ohne ausgeprägte Standortbindung.','Mykorrhiza mit Buche (Fagus), Fichte (Picea) und Eiche (Quercus). Verbreitet in Laub-, Nadel- und Mischwäldern.','experte','Nur jung und nur als bedingt essbar (gut durchgaren, kann Magen-Darm-Beschwerden verursachen) zu sammeln. Kennzeichen: dickliche, weit auseinanderstehende Lamellen, Fleisch rötet erst, dann schwärzt es; alte Fruchtkörper werden komplett schwarz. Als Russula und wegen der Schwärztäubling-Gruppe nur für Geübte: vom essbaren Schwärztäubling (R. nigricans) sind dünnblättrige, schärfer schmeckende oder roh giftige Verwandte abzugrenzen. Im Zweifel stehen lassen.','123pilze, SwissFungi, DGfM',false),
('russula_ochroleuca','Hauptsaison Juli bis November, einer der häufigsten und ausdauerndsten Täublinge bis in den Spätherbst. Erscheint zuverlässig nach Regen in Nadel- und Mischwäldern; in milden, feuchten Herbstwochen massenhaft.','Saure, humose Nadel- und Laubwaldböden; kalkmeidend.','Mykorrhiza mit Fichte (Picea), Buche (Fagus) und Eiche (Quercus). Sehr verbreitet in bodensauren Nadel-, Laub- und Mischwäldern.','experte','Nur bedingt essbar bis minderwertig: der Ockertäubling ist leicht schärflich und gilt vielerorts als nicht empfehlenswert, daher kein Anfänger-Speisepilz. Kennzeichen: schmutzig ocker- bis grüngelber Hut, blass cremefarbenes Sporenpulver, mild bis leicht scharf. Als Täubling (Gattung Russula) nur für Geübte: enge Verwandtschaft mit scharfen, ungeniessbaren gelbhütigen Täublingen. Geschmacksprobe durchführen; scharfe Exemplare verwerfen, im Zweifel stehen lassen.','123pilze, SwissFungi, DGfM',false),
('strobilomyces_strobilaceus','Hauptsaison Juli bis Oktober. Erscheint einzeln und meist nicht häufig einige Tage nach ergiebigen Sommer- und Frühherbstregen in feuchten Laub- und Mischwäldern; warme, durchfeuchtete Spätsommerphasen sind am ergiebigsten.','Frische bis feuchte, humose Wald- und Mischwaldböden, bevorzugt etwas saurer Untergrund.','Mykorrhiza mit Buche, Eiche, Fichte, Tanne und Kiefer. Typisch in feuchten Laub- und Mischwäldern, oft an Wegrändern, Böschungen und in der Krautschicht.','mittel','Unverwechselbares Erkennungsmerkmal: grob abstehend schwarz-graue, schuppig-struppige Hutoberfläche, weisslich-graue Röhren, und das Fleisch verfärbt nach Schnitt erst rötlich, dann schwarz. Nur jung essbar (alt zäh und geschmacklos), gut durchgaren. Aufgrund des charakteristischen Aussehens kaum mit Giftpilzen zu verwechseln; als Röhrling jedoch stets das typische Rot-dann-Schwarz-Verfärben und die struppige Hutoberfläche prüfen.','123pilze, SwissFungi, DGfM, Pilzführer',false),
('suillus_collinitus','Spätsommer bis Spätherbst, Hauptzeit August–November. Wärmeliebende Kalkart; fruchtet schubweise rund 1–2 Wochen nach ergiebigen Regenphasen bei mild-feuchtem Wetter, oft gesellig in kleinen Trupps. Profitiert von warmen, trockenen Sommern mit gelegentlichen Niederschlägen.','Kalkliebend: gedeiht auf basenreichen, kalkhaltigen, eher trockenen und sandig-mageren Böden. Im Gegensatz zum Körnchen-/Butterpilz an Kalk gebunden.','Mykorrhiza streng an zweinadelige Kiefern (Pinus, v.a. Wald-/Schwarzkiefer) gebunden. In lichten Kiefernwäldern, Föhrenforsten, an grasigen Wegrändern, Böschungen und Trockenrasen auf Kalk. Gerne an warmen, sonnigen, südexponierten Stellen.','mittel','Sicher erkennbar an: schmierig-glänzendem, oft rosa-violett überlaufenem braunem Hut, fehlendem Ring am Stiel (im Gegensatz zum Butterpilz Suillus luteus) und namensgebendem rosaroten Myzelfilz an der Stielbasis. Verwechselbar mit anderen Schmierröhrlingen (Suillus) – diese sind alle ungiftig, aber nur als bedingt essbar einzustufen; die abziehbare Huthaut sollte vor dem Verzehr entfernt werden, da sie leicht abführend wirkt. Keine tödlichen Röhrlings-Doppelgänger in der Schweiz.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel, Kalk-Kiefern-Bindung + ringloser schmieriger Hut + rosa Basalfilz korrekt.',false),
('tricholoma_cingulatum','Spätsommer bis in den frühen Winter, Hauptzeit September–November (in milden Lagen bis Dezember). Fruchtet nach Herbstregen bei kühl-feuchter Witterung, meist gesellig in kleinen Gruppen bei seinen Wirtsbäumen.','Bevorzugt feuchte, oft kalkhaltige bis neutrale Böden auf nassen Standorten; an Bach- und Flussufern, in Auböden und feuchten Senken.','Mykorrhiza-Partner von Weide (Salix) und Birke (Betula). In Auwäldern, Parks, an Weiden-/Birkenreihen, Ufergehölzen und feuchten Gebüschen. Eng an das Vorkommen seiner Wirtsbäume in feuchtem Milieu gebunden.','experte','Kennzeichen: grauer, faseriger Hut mit kleinem Buckel, weisse Lamellen, mehliger Geruch und ein deutlicher, häutiger weisser Ring am Stiel (selten bei Erdritterlingen). Wächst nur bei Weide/Birke. ACHTUNG: Die Gattung Tricholoma (Ritterlinge) enthält schwer giftige Arten wie den Tigerritterling (Tricholoma pardinum) sowie den Grünling (T. equestre, Rhabdomyolyse-Verdacht) – die sichere Artbestimmung erfordert Erfahrung. Nur bestimmen, wenn Ring, Standort (Weide/Birke) und Mehlgeruch zweifelsfrei zusammenpassen; im Zweifel stehen lassen.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel, Salix/Betula-Bindung + beringter Stiel + giftige Gattungs-Doppelgänger korrekt.',false),
('vascellum_pratense','Sommer bis Spätherbst, Juni–November. Erscheint wenige Tage bis etwa eine Woche nach Regen auf kurzgrasigen Flächen, oft gesellig in Gruppen oder Reihen; in feuchten Sommern besonders zahlreich.','Auf nährstoffreichen bis mageren Wiesen- und Rasenböden; an offene, kurzgrasige, sonnige Standorte gebunden, kein Waldpilz.','Saprobiont (Streuzersetzer) auf offenem Grünland: Wiesen, Weiden, gemähte Rasen, Park- und Sportanlagen, Böschungen. Wächst direkt im kurzen Gras, nicht bei Bäumen.','experte','Essbar nur im jungen Zustand, solange das Fleisch innen rein weiss und fest ist; sobald es gelblich/olivbraun und pulvrig wird, ungeniessbar. WICHTIG: Jeder kugelige weisse Pilz MUSS längs durchgeschnitten werden – ist im Inneren bereits eine Hut-/Stiel-/Lamellen-Anlage erkennbar, handelt es sich um ein potenziell tödliches Wulstlings-Ei (Amanita, z.B. Grüner Knollenblätterpilz), das einem Stäubling-Ei täuschend ähnlich sieht. Nur durchgehend homogen-weisses Inneres ohne jede Struktur ist ein echter Stäubling. Vom giftverdächtigen Kartoffelbovist (Scleroderma, dunkles Inneres) unterscheiden.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel; HL24-konservativ wegen tödlicher Amanita-Ei-Verwechslung experte.',false),
('xerocomellus_chrysenteron','Sommer bis Spätherbst, Hauptzeit Juli–Oktober (vereinzelt ab Juni, bis November). Fruchtet zuverlässig einige Tage bis zwei Wochen nach Regenphasen über die ganze Saison verteilt, meist einzeln bis in kleinen Gruppen.','Bevorzugt saure bis neutrale, humose Wald- und Wegrandböden; anspruchslos und weit verbreitet.','Mykorrhiza mit Laub- und Nadelbäumen (Eiche, Buche, Fichte, Kiefer). In Laub-, Nadel- und Mischwäldern, an Waldwegen, Böschungen, Lichtungen und Wegrändern; einer der häufigsten Röhrlinge.','mittel','Erkennbar am bräunlich-olivfarbenen, oft felderig aufreissenden Hut mit rötlich gefärbten Rissen, gelben Poren und der namensgebenden Rotfärbung in der Stielrinde; Fleisch blaut beim Anschnitt schwach. Keine tödlichen Röhrlings-Doppelgänger in der Schweiz. Verwechselbar mit anderen Rotfussröhrlingen (X. pruinatus, Hortiboletus) – alle essbar, aber nur jung und madenfrei sammeln, da das weiche Fleisch rasch matschig wird und häufig vom Goldschimmel (Hypomyces) befallen ist.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel, felderig-rissiger Hut + rote Stielrinde + saure Böden korrekt.',false),
('xerocomellus_pruinatus','Spätsommer bis Spätherbst, Hauptzeit Juli/August–November. Etwas spätere und kühletolerantere Saison als der Gemeine Rotfussröhrling; fruchtet nach Regenphasen bei mild-feuchter Witterung, einzeln bis in kleinen Trupps.','Auf sauren, humosen Waldböden; bevorzugt eher etwas frischere, schattige Lagen.','Mykorrhiza vor allem mit Buche, daneben Eiche und Fichte. In Laub- und Mischwäldern, gern auf Buchen-Standorten, an Wegrändern und Lichtungen.','mittel','Vom Gemeinen Rotfussröhrling zu unterscheiden durch den jung bereiften (fein weisslich überpuderten), kräftiger weinrot bis purpurn gefärbten Hut, der weniger felderig aufreisst, und das stärker und rascher blauende Fleisch; junge Röhren leuchtend gelb. Keine tödlichen Röhrlings-Doppelgänger in der Schweiz. Alle Rotfussröhrlinge sind essbar – nur jung, fest und madenfrei verwenden, das Fleisch wird im Alter rasch weich.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel, bereifter purpurner Hut + Buchen-Bindung + stärkeres Blauen korrekt.',false)
